package lexgen

import (
	"strings"
	"testing"
)

func TestGenerateTinySpec(t *testing.T) {
	spec := `%package demo
%receiver d *demo
%states MAIN QUOTE
%%
<MAIN>(?i:if)       { d.keyword() }
<MAIN>[a-z]+        { d.word() }
<MAIN>"             { d.open() }
<QUOTE>[^"]+        { }
<QUOTE><<EOF>>      { d.eof() }
<MAIN><<INVALID>>   { d.invalid() }
`
	generated, err := Generate([]byte(spec), "demo.lex")
	if err != nil {
		t.Fatal(err)
	}
	text := string(generated)
	for _, want := range []string{
		"// Code generated by cooler-lexgen from demo.lex. DO NOT EDIT.",
		"package demo", "genlexMAIN  = 0", "genlexQUOTE = 1",
		"func (d *demo) genlexAction(rule int)", "case 0: // line 5: <MAIN>(?i:if)", "d.keyword()",
		"func (d *demo) genlexEofAction(condition int) bool", "case genlexQUOTE: // line 9",
		"func (d *demo) genlexInvalidAction(condition int) bool", "case genlexMAIN: // line 10",
	} {
		if !strings.Contains(text, want) {
			t.Fatalf("generated source lacks %q:\n%s", want, text)
		}
	}
}

func TestGenerateRejectsBadSpecs(t *testing.T) {
	for _, spec := range []string{
		"%package p\n%%\n<A>x { }\n",
		"%package p\n%receiver r *R\n%states A\n%%\n<B>x { }\n",
		"%package p\n%receiver r *R\n%states A\n%%\n<A>x\n",
		"%package p\n%receiver r *R\n%states A\n%%\n<A>(x { }\n",
		"%package p\n%receiver r *R\n%states A\n%%\n<A>x$ { }\n",
	} {
		if _, err := Generate([]byte(spec), "bad.lex"); err == nil {
			t.Fatalf("expected an error for %q", spec)
		}
	}
}
